/* Consistent next actions, verified deposits, and explicit completed appointments. */
stages.find(s=>s[0]==='scheduled')[1]='Booked appointments';
stages.find(s=>s[0]==='scheduled')[2]='Confirmed visits awaiting attendance';
const stageBeforeFlow=jobStage;jobStage=function(j){if(j.repairAttendanceComplete&&j.status==='Completed'&&!j.finalInvoiceRecorded)return 'invoicing';const stage=stageBeforeFlow(j);if(!j.callout&&!isAssessmentVisit(j)&&approvedQuoteTotal(j)>0&&['new','assessment','quoting','scheduling','deposit','approval'].includes(stage)&&!j.quotes.some(q=>q.status==='Pending'))return depositSummary(j).outstanding>0?'deposit':'scheduling';return stage};
const depositPanelBeforeFlow=depositPanel;depositPanel=function(j){const html=depositPanelBeforeFlow(j);if(!html)return html;const pending=j.invoices.reduce((n,i)=>n+pendingProofs(i).reduce((sum,p)=>sum+cash(p.amount),0),0);return html+(pending&&role==='sevlink'?`<div class="notice"><b>${money(fromCash(pending))} in payment records awaits bank verification.</b><p>A POP does not change the stage until the receipt is verified.</p><button class="primary" onclick="paymentDetails('${j.id}','${j.invoices.find(i=>pendingProofs(i).length).id}')">Review / verify received deposit</button></div>`:'')};
function finishVisitForm(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!['Scheduled','In progress'].includes(j.status))return;const assessment=isAssessmentVisit(j)||j.attendancePurpose==='Assessment';openForm('Mark appointment attended.',`<div id="paymentSaveError" class="notice" role="alert" hidden></div><div class="notice"><b>${esc(property(j.property)?.address)}</b><br>${esc(j.title)}<br>${j.schedule?attendanceTime(j.schedule.when):'Appointment time not recorded'}</div><label>Visit outcome</label><select name="outcome">${assessment?'<option value="assessment">Assessment attended · quote to follow</option>':'<option value="completed">Repair completed · ready to invoice</option><option value="followup">Attended · follow-up visit needed</option>'}</select><label>Shared attendance summary</label><textarea name="notes" rows="4" required maxlength="2500" placeholder="What was attended to, what was done, and the next step. Client-facing Sevlink information only."></textarea><label>Before photos (optional · up to 5 images, 5 MB each)</label><input name="before" type="file" multiple accept="image/jpeg,image/png,image/webp"><small>Existing before photos stay in the report.</small><label>After photos (optional · up to 5 images, 5 MB each)</label><input name="after" type="file" multiple accept="image/jpeg,image/png,image/webp"><label>Checks & recommendations</label><textarea name="checks" rows="3" maxlength="1500" placeholder="Checks performed, test results and any advice or further work needed."></textarea><label>Sevlink report / photo (optional, PDF or image, up to 5 MB)</label><input name="report" type="file" accept="application/pdf,image/jpeg,image/png,image/webp">${j.callout?'<label>Total call-out charge (ZAR)</label><input name="actual" type="number" min="0" step="0.01" required value="'+(j.callout.actualTotal??'')+'"><small>The client budget is '+money(j.callout.totalBudget)+'. Above budget moves the job to Quoting.</small>':''}<p>The client calendar will show Sevlink attended. Subbie identity and price stay private.</p>`,'Save attendance & move job',async data=>{let report,before,after;try{report=await fileData(data.get('report'),quoteTypes);before=await readVisitPhotos(data,'before');after=await readVisitPhotos(data,'after')}catch(e){paymentSaveError(e.message);return}if(await finishVisit(jid,{outcome:data.get('outcome'),notes:data.get('notes'),checks:data.get('checks'),before,after,report,actual:data.get('actual')==null?null:Number(data.get('actual'))})){render();jobDetail(jid,getJob(jid).status==='Completed'?'report':jobStage(getJob(jid))==='quoting'?'quotes':'schedule');toast('Attendance recorded and job moved to the next step.')}})}
async function finishVisit(jid,data){const j=getJob(jid);if(!j||role!=='sevlink'||!['Scheduled','In progress'].includes(j.status)||!data.notes?.trim())return false;const assessment=isAssessmentVisit(j)||j.attendancePurpose==='Assessment';if(!['assessment','completed','followup'].includes(data.outcome)||assessment&&data.outcome!=='assessment'||!assessment&&data.outcome==='assessment')return false;if(j.callout&&(!Number.isFinite(data.actual)||data.actual<0))return paymentSaveError('Enter the total call-out charge.');return commit(()=>{const visit={...(j.schedule||{}),id:id('visit'),when:j.schedule?.when||j.previousVisit?.when||new Date(Date.now()+2*3600000).toISOString().slice(0,16),status:'Attended',attendedAt:now(),outcome:data.outcome,summary:data.notes,checks:data.checks||'',before:data.before||[],after:data.after||[],report:data.report||null};j.visitRecords??=[];j.visitRecords.push(visit);appendVisitPhotos(j,data.before||[],'before');appendVisitPhotos(j,data.after||[],'after');j.previousVisit=visit;j.schedule=null;for(const b of state.privateBookings.filter(b=>b.job===jid&&['Accepted','Awaiting response'].includes(b.status))){b.status='Attended';b.visitOutcome=data.outcome;b.log.push({at:now(),text:'Sevlink recorded the agreed appointment as attended: '+data.outcome})}j.attendancePurpose=null;const over=j.callout&&data.actual>j.callout.totalBudget;if(assessment||over){j.status='New';j.routeOverride='quoting';j.opsAction='quoting';j.assessmentFindings={text:data.notes,at:now()};if(over){j.quoteNeeded={status:'Required',estimatedTotal:data.actual,notes:data.notes,at:now()};j.callout.outcome='quote'}}else if(data.outcome==='followup'){j.status='Awaiting schedule';j.routeOverride=null;j.opsAction='scheduling'}else{j.status='Completed';j.completedAt=now();j.completionNotes=data.notes;j.completionChecks=data.checks?.trim()||j.completionChecks||'';j.repairAttendanceComplete=true;j.finalInvoiceRecorded=false;if(j.callout)j.callout.actualTotal=data.actual}j.comments.push({author:'Sevlink',text:'Sevlink attended: '+data.notes,visibility:'shared',at:now()});addEvent(j,assessment?'Assessment attended':data.outcome==='completed'?'Repair appointment completed':'Appointment attended',data.notes);notify(j,'Appointment attended',j.ref+': Sevlink attended. '+(assessment||over?'Quote to follow.':data.outcome==='followup'?'A follow-up visit will be arranged.':'Work completed; invoice to follow.'))})}
recordAttendance=function(jid){finishVisitForm(jid)};
const completionBeforeFlow=completionForm;completionForm=function(jid){const j=getJob(jid);if(j&&['Scheduled','In progress'].includes(j.status))return finishVisitForm(jid);return completionBeforeFlow(jid)};
const addInvoiceBeforeFlow=addCompanyInvoice;addCompanyInvoice=async function(jid,data){const result=await addInvoiceBeforeFlow(jid,data);if(result){const j=getJob(jid);if(j?.repairAttendanceComplete){await commit(()=>{j.finalInvoiceRecorded=true})}}return result};
const summaryBeforeFlow=scheduleSummary;scheduleSummary=function(j){if(j.schedule)return summaryBeforeFlow(j);const v=j.visitRecords?.at(-1);return v?`<div class="notice"><b>✓ Sevlink attended · ${v.outcome==='assessment'?'quote to follow':v.outcome==='followup'?'follow-up needed':'work completed'}</b><br>${attendanceTime(v.when)}<p>${esc(v.summary)}</p></div>`:summaryBeforeFlow(j)};
const scheduleRenderBeforeFlow=renderSchedule;renderSchedule=function(j){if(!j.schedule&&j.visitRecords?.length){const v=j.visitRecords.at(-1);$('#jobcontent').innerHTML=scheduleSummary(j)+(v.report?'<button class="secondary" id="visitReportDownload">Download Sevlink visit report</button>':'')+(j.status==='Completed'?'<p>Work is completed. Invoices and payments are under the Invoices tab.</p>':'<p>The previous visit is recorded. Sevlink will arrange the next step.</p>');if(v.report)$('#visitReportDownload').onclick=()=>download(v.report);if(j.status!=='Completed'&&j.status==='Awaiting schedule'&&role==='sevlink')$('#jobcontent').insertAdjacentHTML('beforeend',`<button class="primary" onclick="bookingForm('', '${j.id}')">Book follow-up visit</button>`);return}scheduleRenderBeforeFlow(j)};
const detailBeforeFlow=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeFlow(jid,section);const j=getJob(jid);if(!j)return;if(role==='sevlink'&&['Scheduled','In progress'].includes(j.status)){$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Next step: record this visit once attendance is finished.</b><p><button class="primary" onclick="finishVisitForm('${j.id}')">Mark appointment attended</button></p></div>`);if($('#complete'))$('#complete').textContent='Mark appointment attended'}if(role==='sevlink'&&jobStage(j)==='scheduling')$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Ready to schedule</b><p><button class="primary" onclick="bookingForm('', '${j.id}')">Book agreed appointment</button></p></div>`)};
calendarJobs=function(){return visibleJobs().flatMap(j=>[...(j.schedule&&['Confirmed','Attended'].includes(j.schedule.status)?[{...j,schedule:{...j.schedule,status:j.status==='Completed'?'Attended':j.schedule.status}}]:[]),...(j.visitRecords||[]).filter(v=>v.when).map(v=>({...j,schedule:v}))])};


async function confirmExistingFinalInvoice(jid){const j=getJob(jid);if(role!=='sevlink'||!j||j.status!=='Completed')return;const required=j.callout?(j.callout.actualTotal??j.callout.totalBudget):approvedQuoteTotal(j);if(j.invoices.reduce((n,i)=>n+cash(i.amount),0)<cash(required)){paymentSaveError('Upload the remaining invoice amount first.');return}if(await commit(()=>j.finalInvoiceRecorded=true)){render();jobDetail(jid,'invoices')}}
const detailBeforeFinalReview=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeFinalReview(jid,section);const j=getJob(jid);if(role==='sevlink'&&j?.repairAttendanceComplete&&!j.finalInvoiceRecorded&&j.invoices.length)$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Review the final invoice</b><p>If the full job invoice was already uploaded, confirm it here. Otherwise upload the remaining balance.</p><button class="secondary" onclick="confirmExistingFinalInvoice('${j.id}')">Existing invoice covers completed work</button></div>`)};


const nextActionBeforeFlow=nextAction;nextAction=function(j){if(jobStage(j)==='deposit'&&j.invoices.some(i=>pendingProofs(i).length))return 'Payment proof recorded — Sevlink must verify receipt in the bank to release this booking.';if(jobStage(j)==='scheduled')return 'Attend the booked appointment, then mark the visit attended.';if(jobStage(j)==='invoicing')return 'Work completed. Upload the final invoice or review the existing full invoice.';return nextActionBeforeFlow(j)};


function remainingDepositAction(j){if(role==='tenant'||j.callout)return '';const d=depositSummary(j);if(d.outstanding<=0)return '';const outstanding=j.invoices.find(i=>invoiceBalance(i)>0&&(i.purpose==='Deposit'||i.purpose==='Full'||!i.purpose));return `<div class="notice" style="margin:12px 0"><b>Deposit still to receive: ${money(d.outstanding)}</b><p>Deposit target ${money(d.required)} · Verified received ${money(d.received)}</p>${outstanding?`<button class="primary" onclick="depositInstalmentForm('${j.id}','${outstanding.id}')">${role==='sevlink'?'Record another deposit payment':'Upload another deposit POP'}</button><p>Apply the next instalment to ${esc(outstanding.number)}. The invoice can receive multiple payments until its balance is settled.</p>`:role==='sevlink'?`<button class="primary" onclick="invoiceForm('${j.id}')">Upload remaining deposit invoice · ${money(d.outstanding)}</button><p>The previous invoice is settled. Upload a supplementary deposit invoice using its own company invoice number, then record the additional payment.</p>`:'<p>The previous invoice is settled. Sevlink needs to upload an invoice for the remaining deposit before you can attach the next POP.</p>'}</div>`}
const depositPanelBeforeInstalments=depositPanel;depositPanel=function(j){return depositPanelBeforeInstalments(j)+remainingDepositAction(j)};
function depositInstalmentForm(jid,iid){paymentForm(jid,iid);const j=getJob(jid),i=findInvoice(jid,iid);if(!j||!i)return;const purpose=modal.querySelector('select[name="purpose"]'),amount=modal.querySelector('input[name="amount"]');if(purpose)purpose.value='Deposit';if(amount)amount.value=Math.min(invoiceBalance(i),depositSummary(j).outstanding)};


function depositExceptionActive(j){return j?.depositException?.status==='Authorised'&&j.depositException.quoteKey===j.quotes.filter(q=>q.status==='Approved').map(q=>q.id+':'+cash(q.amount)).sort().join('|')}
async function authoriseDepositException(jid,reason,staffId,newStaffName=''){const j=getJob(jid);const staff=state.sevlinkStaff?.find(s=>s.id===staffId);if(!staff&&!(staffId==='new'&&newStaffName.trim()))return false;if(role!=='sevlink'||!j||j.callout||approvedQuoteTotal(j)<=0||!reason?.trim()||['Completed','In progress','Scheduled'].includes(j.status))return false;return commit(()=>{const authoriser=staff||{id:id('staff'),name:newStaffName.trim()};if(!staff)state.sevlinkStaff.push(authoriser);j.depositException={status:'Authorised',reason:reason.trim(),staffId:authoriser.id,by:authoriser.name,recordedBy:person(),at:now(),shortfallAtApproval:depositSummary(j).outstanding,quoteKey:j.quotes.filter(q=>q.status==='Approved').map(q=>q.id+':'+cash(q.amount)).sort().join('|')};financialAudit(j,authoriser.name+' authorised work before full deposit. Amount still owing: '+money(depositSummary(j).outstanding)+'. Reason: '+reason.trim());addEvent(j,'Booking authorised by Sevlink','Sevlink has authorised arranging the repair appointment.');j.history.push(authoriser.name+' approved a deposit exception. Payment balances are unchanged.')})}
function depositExceptionForm(jid){const j=getJob(jid);if(role!=='sevlink'||!j)return;openForm('Authorise work before full deposit.',`<div class="notice">${esc(j.ref)} · ${esc(j.title)}<br>Deposit still unpaid: <b>${money(depositSummary(j).outstanding)}</b><br>This releases scheduling only. It does not record a payment or reduce the amount due.</div><label>Authorised by (required)</label><select name="staff" id="depositAuthoriser" required><option value="">Choose the Sevlink staff member</option>${(state.sevlinkStaff||[]).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}<option value="new">＋ Add a Sevlink staff name</option></select><div id="newDepositAuthoriser" hidden><label>Staff member’s full name</label><input name="newStaffName" id="newDepositAuthoriserName" maxlength="180"></div><small>Demo name selection. Live authorisation must use the signed-in staff account.</small><label>Private Sevlink reason</label><textarea name="reason" required rows="4" maxlength="1500" placeholder="e.g. Trusted agency with agreed payment terms."></textarea><label style="display:flex;gap:10px"><input name="confirmed" type="checkbox" required style="width:auto">I authorise work to proceed and understand the unpaid amount remains due.</label>`,'Authorise & move to Ready to schedule',async d=>{if(d.get('confirmed')&&await authoriseDepositException(jid,d.get('reason'),d.get('staff'),d.get('newStaffName')||'')){render();jobDetail(jid,'schedule');toast('Scheduling authorised. The unpaid balance is unchanged.')}});$('#depositAuthoriser').onchange=()=>{const fresh=$('#depositAuthoriser').value==='new';$('#newDepositAuthoriser').hidden=!fresh;$('#newDepositAuthoriserName').required=fresh}}
const needsDepositBeforeException=needsDeposit;needsDeposit=function(j){return !depositExceptionActive(j)&&needsDepositBeforeException(j)};
const stageBeforeException=jobStage;jobStage=function(j){const stage=stageBeforeException(j);return stage==='deposit'&&depositExceptionActive(j)?'scheduling':stage};
const panelBeforeException=depositPanel;depositPanel=function(j){let html=panelBeforeException(j);if(role==='tenant'||j.callout||approvedQuoteTotal(j)<=0)return html;if(depositExceptionActive(j))html+=`<div class="notice"><b>Sevlink authorised scheduling before full deposit.</b><p>The unpaid amount remains on the job balance.</p>${role==='sevlink'?`<p>Authorised by ${esc(j.depositException.by)} · ${date(j.depositException.at)}<br>Private reason: ${esc(j.depositException.reason)}</p>`:''}</div>`;else if(role==='sevlink'&&needsDepositBeforeException(j))html+=`<div class="notice"><b>Trusted client / agreed terms?</b><p><button class="secondary" onclick="depositExceptionForm('${j.id}')">Authorise work before full deposit</button></p></div>`;return html};
function jobBalanceSummary(j){if(role==='tenant'||j.callout||approvedQuoteTotal(j)<=0)return '';const total=approvedQuoteTotal(j),received=depositSummary(j).received,billed=fromCash(j.invoices.reduce((n,i)=>n+cash(i.amount),0)),existingDue=fromCash(j.invoices.reduce((n,i)=>n+cash(invoiceBalance(i)),0));return `<div class="notice"><b>Full job balance</b><p>Approved work: ${money(total)}<br>Verified payments received: ${money(received)}<br><b>Total still to pay: ${money(fromCash(Math.max(0,cash(total)-cash(received))))}</b><br>Already invoiced and unpaid: ${money(existingDue)}<br>Still to invoice: ${money(fromCash(Math.max(0,cash(total)-cash(billed))))}</p><p>Any unpaid deposit invoice stays due alongside the final invoice. Already invoiced amounts are not charged again.</p></div>`}
const invoicesBeforeJobBalance=renderInvoices;renderInvoices=function(j){invoicesBeforeJobBalance(j);if(role!=='tenant')$('#jobcontent').insertAdjacentHTML('afterbegin',jobBalanceSummary(j))};
const invoiceFormBeforeJobBalance=invoiceForm;invoiceForm=function(jid){invoiceFormBeforeJobBalance(jid);const j=getJob(jid);if(j&&role==='sevlink'&&$('#form'))$('#form').insertAdjacentHTML('afterbegin',jobBalanceSummary(j))};


const normaliseBeforeStaffAuthorisation=normalise;normalise=function(){normaliseBeforeStaffAuthorisation();state.sevlinkStaff??=[{id:'sevlink-michael',name:'Michael Barnard'}]};
const detailBeforeAuthoriser=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeAuthoriser(jid,section);const j=getJob(jid);if(role==='sevlink'&&j&&depositExceptionActive(j))$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice" style="border:2px solid #e9b44c"><b>Deposit exception authorised by ${esc(j.depositException.by)}</b><p>${date(j.depositException.at)}<br>Unpaid deposit when authorised: ${money(j.depositException.shortfallAtApproval)}<br>Reason: ${esc(j.depositException.reason)}</p></div>`)};


const stageBeforeInvoiceHandoff=jobStage;jobStage=function(j){if(j.status==='Completed'&&j.invoices.length){const total=j.callout?(j.callout.actualTotal??j.callout.totalBudget)+(j.quotes.find(q=>q.status==='Approved'&&q.approvedForFollowup)?.amount||0):approvedQuoteTotal(j),billed=j.invoices.reduce((n,i)=>n+cash(i.amount),0);if((total<=0||billed>=cash(total))&&(j.finalInvoiceRecorded||!j.repairAttendanceComplete))return j.invoices.some(i=>invoiceBalance(i)>0||pendingProofs(i).length)?'payment':'closed'}return stageBeforeInvoiceHandoff(j)};
const invoiceFormBeforeValidation=invoiceForm;invoiceForm=function(jid){invoiceFormBeforeValidation(jid);$('#form')?.addEventListener?.('invalid',event=>{const names={number:'company invoice number',file:'invoice PDF / image',issueDate:'invoice date',dueDate:'due date',amount:'invoice amount',billTo:'bill-to name',email:'recipient email'};paymentSaveError('Check the '+(names[event.target.name]||'required invoice field')+'. '+(event.target.validationMessage||''))},true)};


async function readVisitPhotos(data,key){const files=(typeof data.getAll==='function'?data.getAll(key):[data.get(key)]).filter(f=>f?.size);if(files.length>5)throw Error('Choose no more than 5 '+key+' photos at a time.');return Promise.all(files.map(file=>fileData(file,imageTypes)))}
function appendVisitPhotos(j,photos,phase){for(const file of photos){const photo={...file,phase,at:now()};j.photos.push(photo);j[phase==='before'?'beforePhotos':'afterPhotos'].push(photo)}}
function editCompletionReportForm(jid){const j=getJob(jid);if(role!=='sevlink'||!j||j.status!=='Completed')return;openForm('Edit work completion report.',`<div id="paymentSaveError" class="notice" role="alert" hidden></div><label>Work carried out</label><textarea name="notes" required rows="4" maxlength="2500">${esc(j.completionNotes||'')}</textarea><label>Add before photos (up to 5, 5 MB each)</label><input name="before" type="file" multiple accept="image/jpeg,image/png,image/webp"><label>Add after photos (up to 5, 5 MB each)</label><input name="after" type="file" multiple accept="image/jpeg,image/png,image/webp"><label>Checks & recommendations</label><textarea name="checks" rows="3" maxlength="1500">${esc(j.completionChecks||'')}</textarea><p>Existing photos stay in the report. Editing the report does not change invoices, payments or attendance.</p>`,'Save report',async data=>{if(role!=='sevlink'||!getJob(jid))return;let before,after;try{before=await readVisitPhotos(data,'before');after=await readVisitPhotos(data,'after')}catch(e){paymentSaveError(e.message);return}if(await commit(()=>{j.completionNotes=data.get('notes');j.completionChecks=data.get('checks');appendVisitPhotos(j,before,'before');appendVisitPhotos(j,after,'after');addEvent(j,'Completion report updated','Sevlink updated the work summary, report photos and recommendations.')})){render();jobDetail(jid,'report')}})}
const detailBeforeReportFields=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeReportFields(jid,section);const j=getJob(jid);if(role==='sevlink'&&j?.status==='Completed'&&section==='report')$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="actions"><button class="secondary" onclick="editCompletionReportForm('${j.id}')">Edit report / add photos</button></div>`)};

async function markJobOnSite(jid){const j=getJob(jid);if(role!=='sevlink'||!j||j.status!=='Scheduled'||j.schedule?.status!=='Confirmed')return false;const saved=await commit(()=>{j.status='In progress';j.opsActionBeforeOnSite=j.opsAction;j.onSiteAt=now();j.schedule.onSiteAt=j.onSiteAt;for(const b of state.privateBookings.filter(b=>b.job===jid&&b.status==='Accepted'&&b.when===j.schedule.when)){b.onSiteAt=j.onSiteAt;b.log.push({at:now(),text:'Sevlink recorded arrival on site.'})}addEvent(j,'Sevlink on site','Arrival recorded by Sevlink. The visit is underway.');notify(j,'Sevlink on site',j.ref+': Sevlink is on site and the visit is underway.')});if(saved){render();toast('Marked on site. Job moved to Work underway.')}return saved}
const jobDetailBeforeOnSite=jobDetail;jobDetail=function(jid,section='comments'){jobDetailBeforeOnSite(jid,section);const j=getJob(jid);if(role==='sevlink'&&j?.status==='Scheduled'&&j.schedule?.status==='Confirmed')$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice" id="onsiteJobAction"><b>Has the team arrived?</b><p>${esc(property(j.property)?.address)}<br>${esc(j.title)} · ${j.ref}<br>${attendanceTime(j.schedule.when)}</p><p><button class="primary" onclick="markJobOnSite('${j.id}').then(saved=>{if(saved)jobDetail('${j.id}','schedule')})">Mark on site</button></p></div>`);if(j?.status==='In progress'&&j.onSiteAt)$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Sevlink on site</b><br>Arrival recorded: ${date(j.onSiteAt)}</div>`)};
const bookingDetailBeforeOnSite=privateBookingDetail;privateBookingDetail=function(bid){bookingDetailBeforeOnSite(bid);if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid),j=b&&getJob(b.job);if(j?.status==='Scheduled'&&j.schedule?.when===b.when)modal.insertAdjacentHTML('afterbegin',`<div class="notice"><button class="primary" onclick="markJobOnSite('${j.id}').then(saved=>{if(saved)privateBookingDetail('${bid}')})">Mark on site · update job</button></div>`);if(b?.onSiteAt)modal.insertAdjacentHTML('afterbegin',`<div class="notice"><b>On site</b> · ${date(b.onSiteAt)}</div>`)};
const summaryBeforeOnSite=scheduleSummary;scheduleSummary=function(j){if(j.status==='In progress'&&j.onSiteAt)return `<div class="notice"><b>Sevlink on site · work underway</b><br>Arrived: ${date(j.onSiteAt)}<br>Booked: ${attendanceTime(j.schedule?.when||j.previousVisit?.when)}</div>`;return summaryBeforeOnSite(j)};

function openCalendarAppointment(jid,when){const j=getJob(jid);if(!j)return;jobDetail(jid,'schedule');if(j.schedule?.when!==when){$('#onsiteJobAction')?.remove();const visit=j.visitRecords?.find(v=>v.when===when);$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Selected past appointment</b><p>${attendanceTime(when)}<br>${esc(visit?.summary||'Attendance is recorded in the job history.')}</p><p>This entry is historical. Any new visit is a separate appointment.</p></div>`)}}
